function validate([costs]) {
  if (!Array.isArray(costs) || costs.length < 1 || costs.length > 100) return 'costs needs 1 to 100 rows (houses).';
  const k = costs[0].length;
  if (k < 2 || k > 20) return 'Each row needs 2 to 20 colors.';
  for (const row of costs) {
    if (row.length !== k) return 'Every row must have the same number of colors.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 20)) return 'Each cost is a whole number from 1 to 20.';
  }
  return null;
}

