function minCostII(costs) {
  const k = costs[0].length;
  let dp = [...costs[0]];

  for (let house = 1; house < costs.length; house++) {
    let bestColor = 0;
    for (let color = 1; color < k; color++) {
      if (dp[color] < dp[bestColor]) {
        bestColor = color;
      }
    }
    let secondBest = Infinity;
    for (let color = 0; color < k; color++) {
      if (color !== bestColor) {
        secondBest = Math.min(secondBest, dp[color]);
      }
    }
    const next = [];
    for (let color = 0; color < k; color++) {
      const previous = color === bestColor ? secondBest : dp[bestColor];
      next.push(costs[house][color] + previous);
    }
    dp = next;
  }
  return Math.min(...dp);
}

