function minCostII(costs) {
  // Top-down memoised search: the cheapest way to paint houses from `house` on, given this house's color.
  const memo = new Map();
  const cheapest = (house, color) => {
    const key = house * 100 + color;
    if (memo.has(key)) return memo.get(key);
    let rest = 0;
    if (house + 1 < costs.length) {
      rest = Infinity;
      for (let other = 0; other < costs[0].length; other++) if (other !== color) rest = Math.min(rest, cheapest(house + 1, other));
    }
    memo.set(key, costs[house][color] + rest);
    return costs[house][color] + rest;
  };
  let answer = Infinity;
  for (let color = 0; color < costs[0].length; color++) answer = Math.min(answer, cheapest(0, color));
  return answer;
}

