function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const n = size === 'large' ? 100 : 1 + pick(6);
  const k = size === 'large' ? 20 : 2 + pick(4);
  const top = size === 'large' || rand() < 0.6 ? 20 : 1 + pick(4);
  return [Array.from({ length: n }, () => Array.from({ length: k }, () => 1 + pick(top)))];
}
